using System.Windows;
using System.Windows.Controls;
using System.Windows.Media;
namespace DomainConsole;
public partial class MainWindow {
 async void CheckConnection_Click(object s,RoutedEventArgs e)=>await Guard(async()=>{
  var row=Current();if(!await EnsureEndpointCredentials(new(){row}))return;var window=new Window{Owner=this,Title="Подключение · "+row.Name,Width=720,Height=400,MinWidth=480,MinHeight=260,WindowStartupLocation=WindowStartupLocation.CenterOwner};var panel=new DockPanel{Margin=new(16)};var status=new TextBlock{Text="Проверка WinRM: "+row.Host+"…",TextWrapping=TextWrapping.Wrap,FontWeight=FontWeights.SemiBold,Margin=new(0,0,0,10)};DockPanel.SetDock(status,Dock.Top);panel.Children.Add(status);var edit=new Button{Content="Адрес подключения…",HorizontalAlignment=HorizontalAlignment.Left,ToolTip="Задать или изменить IP/VPN-адрес; возврат к имени AD"};DockPanel.SetDock(edit,Dock.Top);edit.Click+=async(s,a)=>{window.Close();await EditConnection(row,"");};panel.Children.Add(edit);var details=new TextBox{IsReadOnly=true,AcceptsReturn=true,TextWrapping=TextWrapping.Wrap,VerticalScrollBarVisibility=ScrollBarVisibility.Auto,FontFamily=new FontFamily("Consolas")};var expander=new Expander{Header="Технические подробности",Content=details,IsExpanded=false};panel.Children.Add(expander);window.Content=panel;window.Show();try{var result=await remote.CheckConnection(row.Target);ConnectionSucceeded(row.Host);try{ApplyClientSnapshot(row.Host,await remote.ReadRebootState(row.Target));}catch(Exception probeError){RecordStatusDiagnostic(row.Host,new(){CollectedUtc=DateTime.UtcNow.ToString("o"),Error=probeError.Message});}status.Text="Подключение успешно · "+row.Host+"\n"+result;status.Foreground=Brushes.DarkGreen;details.Text=result;}catch(Exception ex){ConnectionFailed(row.Host,ex.Message);status.Text="Подключение не установлено · "+row.Host+"\n"+ShortConnectionError(ex.Message)+"\nУчётная запись: "+ConnectionStore.DescribeAccount(row.Target)+". Команды из редактора не запускались.";status.Foreground=Brushes.Firebrick;details.Text=ex.Message+"\n"+ConnectionStore.AuthenticationAdvice(ex.Message);}finally{RefreshOutcomes();if(IsCurrent(row))UpdateWsusStage();}
 });
 public static string ShortConnectionError(string message){var line=message.Split(new[]{'\r','\n'},StringSplitOptions.RemoveEmptyEntries).FirstOrDefault()??"Причина не получена";return line.Length>650?line[..650]+"…":line;}
}
